/** Fresh finance-only schema; SQL/privileges are real, identity/rule facts are an explicit test port. */
@EnabledIfEnvironmentVariable(named="IAS_FINANCE_VALIDATION_URL",matches="jdbc:mysql://127\\.0\\.0\\.1:3307/(?:qa_finance|ias_finance_n1)_[a-z0-9_]+.*")
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
class FinanceMySqlTest {
 @Test @Order(1) void chargedQuoteConfirmationAuditRollbackOriginalKeyAndMinimumPrivileges()throws Exception{
  String url=System.getenv("IAS_FINANCE_VALIDATION_URL");var ownerDb=new JdbcTemplate(new DriverManagerDataSource(url,System.getenv("IAS_FINANCE_VALIDATION_OWNER"),System.getenv("IAS_FINANCE_VALIDATION_OWNER_PASSWORD")));
  var guard=ownerDb.queryForMap("SELECT @@port port,DATABASE() db,@@datadir datadir");assertEquals(3307,((Number)guard.get("port")).intValue());assertEquals("C:/ias-local/Develop/IAS-MySQL84/data/",guard.get("datadir").toString().replace('\\','/'));String schema=guard.get("db").toString(),user=System.getenv("IAS_FINANCE_VALIDATION_USER");assertTrue(schema.matches("(?:qa_finance|ias_finance_n1)_[a-z0-9_]+"));assertTrue(user.matches("[a-z0-9_]{1,32}"));
  for(String migration:List.of("V1__finance_group.sql","V2__customer_quote_confirmation.sql","V3__quote_decision.sql","V4__money_ledger.sql","V5__quote_source_intent.sql","V8__money_closure.sql","V9__money_notification_owner.sql","V10__money_notification_delivery.sql","V11__money_review_facts.sql","V12__correction_review_attestation.sql")){try(var in=getClass().getResourceAsStream("/db/migration/"+migration)){String ddl=new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);for(String statement:ddl.split(";"))if(!statement.isBlank())ownerDb.execute(statement);}}
  for(String table:List.of("finance_fee_group","finance_operation","finance_quote_version","finance_cost_fact","finance_approval_fact","finance_audit","finance_outbox","finance_customer_confirmation","finance_approval_request","finance_quote_decision","finance_money_account","finance_money_entry","finance_money_reference","finance_quote_source","finance_quote_source_event","finance_quote_source_outbox","finance_receivable_execution_fact","finance_money_terminal_fact","finance_money_notification_delivery","finance_money_review","finance_money_review_event","finance_correction_attestation"))ownerDb.execute("GRANT SELECT,INSERT ON "+schema+"."+table+" TO '"+user+"'@'127.0.0.1'");
  ownerDb.execute("GRANT UPDATE(row_version,q_cents,c_cents,h_cents,b_cents,ever_required_finance,first_trigger_application_id,first_trigger_rule_version,first_trigger_group_version,state_json,updated_at) ON "+schema+".finance_fee_group TO '"+user+"'@'127.0.0.1'");
  ownerDb.execute("GRANT UPDATE(row_version,receivable_cents,collected_cents,refunded_cents,settled_cents,overpayment_cents,state_json,updated_at) ON "+schema+".finance_money_account TO '"+user+"'@'127.0.0.1'");
  ownerDb.execute("GRANT UPDATE(source_state,result_digest,updated_at) ON "+schema+".finance_quote_source TO '"+user+"'@'127.0.0.1'");
  ownerDb.execute("GRANT UPDATE(state,attempts,next_attempt_at,lease_id,lease_until,delivered_at,last_error_code,updated_at) ON "+schema+".finance_money_notification_delivery TO '"+user+"'@'127.0.0.1'");
  var source=new DriverManagerDataSource(url,user,System.getenv("IAS_FINANCE_VALIDATION_PASSWORD"));var db=new JdbcTemplate(source);Actor employee=new Actor(1,10),customer=new Actor(1,99);Identity owner=new Identity(1,2,UUID.randomUUID());
  Access access=new Access(){public void current(Actor a,Identity o,String action){if(a.tenantId()!=1||!o.equals(owner))throw new SecurityException();}public void submission(Actor a,Identity o,Submit c,QuoteDetails d){}public void approval(Actor a,Identity o,UUID id,ApprovalFact f){}public void execution(Actor a,Identity o,UUID id){}public void verifiedCost(Actor a,Identity o,CostFact f){}public void customerConfirmation(Actor a,Identity o,QuoteVersion q){if(!a.equals(customer))throw new SecurityException();}};
  var store=new JdbcFeeGroups(source,access);store.open(employee,owner,UUID.randomUUID());UUID quote=UUID.randomUUID(),line=UUID.randomUUID();var command=new Submit(UUID.randomUUID(),quote,0,Set.of(),List.of(new PlanLine(line,UUID.randomUUID(),UUID.randomUUID(),250000,false)),new PublishedRule("PUBLISHED_MYSQL_V1",200000));store.submit(employee,owner,command,new QuoteDetails(true,"真实MySQL报价确认事务验证",Map.of(line,"LABOR")));
  assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM finance_approval_request",Long.class));UUID op=UUID.randomUUID();ownerDb.execute("ALTER TABLE finance_audit ADD CONSTRAINT qa_finance_confirm CHECK(action_name<>'CUSTOMER_QUOTE_CONFIRMED')");
  var fault=assertThrows(java.sql.SQLException.class,()->store.confirm(customer,owner,op,1,quote,1));assertEquals(3819,fault.getErrorCode());assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM finance_customer_confirmation",Long.class));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM finance_approval_request",Long.class));assertEquals(2,db.queryForObject("SELECT COUNT(*) FROM finance_operation",Long.class));assertEquals(1,store.read(employee,owner).version());ownerDb.execute("ALTER TABLE finance_audit DROP CHECK qa_finance_confirm");
  try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var gate=new CountDownLatch(1);var calls=new ArrayList<Future<Receipt>>();for(int i=0;i<6;i++)calls.add(pool.submit(()->{gate.await();return store.confirm(customer,owner,op,1,quote,1);}));gate.countDown();var first=calls.getFirst().get();for(var call:calls)assertEquals(first,call.get());}
  assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM finance_customer_confirmation",Long.class));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM finance_approval_request",Long.class));assertEquals(3,db.queryForObject("SELECT COUNT(*) FROM finance_operation",Long.class));assertEquals(3,db.queryForObject("SELECT COUNT(*) FROM finance_audit",Long.class));assertEquals(3,db.queryForObject("SELECT COUNT(*) FROM finance_outbox",Long.class));assertEquals(250000,store.read(customer,owner).bCents());assertTrue(store.read(customer,owner).everRequiredFinance());assertEquals(0,store.read(customer,owner).highestApprovedCents());assertEquals(store.confirm(customer,owner,op,1,quote,1),store.operation(customer,owner,op));
  assertThrows(Exception.class,()->db.execute("CREATE TABLE forbidden(id INT)"));assertThrows(Exception.class,()->db.update("DELETE FROM finance_customer_confirmation"));assertThrows(Exception.class,()->db.update("UPDATE finance_approval_request SET basis_json='{}'"));assertThrows(Exception.class,()->db.queryForList("SELECT id FROM ias_identity_test.tenant LIMIT 1"));
 }
 @Test @Order(2) void quoteDecisionsAndMoneyLedgerUnderRealMinimumPrivileges()throws Exception{FinanceLedgerMySqlCases.run();}
 @Test @Order(3) void sourceIntentAbortCommitAndMinimumPrivileges()throws Exception{QuoteSourceMySqlCases.run();}
 @Test @Order(4) void completedApprovalMirrorManualMoneyAndAtomicRebooking()throws Exception{CompletionMoneyMySqlCases.run();}
 @Test @Order(5) void notificationDeliveryFailureRestartAndLostAckRecovery(){String url=System.getenv("IAS_FINANCE_VALIDATION_URL");var source=new DriverManagerDataSource(url,System.getenv("IAS_FINANCE_VALIDATION_USER"),System.getenv("IAS_FINANCE_VALIDATION_PASSWORD"));var db=new JdbcTemplate(source);var tx=new org.springframework.transaction.support.TransactionTemplate(new org.springframework.jdbc.datasource.DataSourceTransactionManager(source));var target=db.queryForObject("SELECT event_id FROM finance_money_notification_delivery ORDER BY updated_at DESC LIMIT 1",String.class);var first=new FinanceNotificationDelivery(db,tx,event->{throw new IllegalStateException("NOTIFICATION_UNAVAILABLE");});first.tick();assertEquals("PENDING",db.queryForObject("SELECT state FROM finance_money_notification_delivery WHERE event_id=?",String.class,target));db.update("UPDATE finance_money_notification_delivery SET next_attempt_at=TIMESTAMPADD(SECOND,-1,CURRENT_TIMESTAMP(3)) WHERE event_id=?",target);var recovered=new FinanceNotificationDelivery(db,tx,event->Map.of("eventId",event.get("eventId"),"ack","COMMITTED_DUPLICATE"));recovered.tick();assertEquals("DELIVERED",db.queryForObject("SELECT state FROM finance_money_notification_delivery WHERE event_id=?",String.class,target));}
 @Test @Order(6) @SuppressWarnings("unchecked") void authoritativeProjectionReadsRealOwnerRowsAndRejectsAlteredOwnerFact()throws Exception{
  String url=System.getenv("IAS_FINANCE_VALIDATION_URL");var source=new DriverManagerDataSource(url,System.getenv("IAS_FINANCE_VALIDATION_USER"),System.getenv("IAS_FINANCE_VALIDATION_PASSWORD"));var db=new JdbcTemplate(source);var row=db.queryForMap("SELECT m.tenant_id,m.customer_company_id,m.fault_group_id,m.completion_id,q.quote_json FROM finance_approval_completion_mirror m JOIN finance_quote_version q ON q.tenant_id=m.tenant_id AND q.application_id=m.quote_id ORDER BY m.recorded_at DESC LIMIT 1");long tenant=((Number)row.get("tenant_id")).longValue(),company=((Number)row.get("customer_company_id")).longValue();UUID group=UUID.fromString(row.get("fault_group_id").toString()),completion=UUID.fromString(row.get("completion_id").toString());var quote=FinanceController.JSON.readValue(row.get("quote_json").toString(),QuoteVersion.class);var approved=quote.command().additions().getFirst();Actor actor=new Actor(tenant,10);Identity owner=new Identity(tenant,company,group);
  Access authority=new Access(){public void current(Actor a,Identity o,String action){if(!actor.equals(a)||!owner.equals(o))throw new SecurityException();}public void submission(Actor a,Identity o,Submit c,QuoteDetails d){}public void approval(Actor a,Identity o,UUID id,ApprovalFact f){}public void execution(Actor a,Identity o,UUID id){}public void verifiedCost(Actor a,Identity o,CostFact f){}};FinanceAccess access=new FinanceAccess(){public Principal principal(HttpServletRequest r,boolean w){return new Principal(actor,"EMPLOYEE");}public Scope scope(HttpServletRequest r,Principal p,UUID t){throw new UnsupportedOperationException();}public PublishedRule rule(HttpServletRequest r){throw new UnsupportedOperationException();}public Access bind(HttpServletRequest r,Principal p){return authority;}};HttpServletRequest request=mock(HttpServletRequest.class);when(request.getHeaders("Cookie")).thenReturn(Collections.enumeration(List.of("IAS-SESSION-DEV=mysql")));
  FeeExecutionProjectionController.Peer exact=(edge,path,body,r)->{var response=new LinkedHashMap<String,Object>(body);response.remove("sessionToken");response.put("tenantId",Long.toString(tenant));response.put("companyId",Long.toString(company));response.put("state","PROJECTION");response.put("items",List.of(Map.of("lineId",approved.id().toString(),"ticketId",approved.ticketId().toString(),"roundId",approved.roundId().toString(),"kind","LABOR","state","EXECUTED","amountCents","200000","executionReceiptId",UUID.randomUUID().toString())));return response;};var result=new FeeExecutionProjectionController(source,access,exact).projection(group.toString(),completion.toString(),request);assertEquals("250000",result.get("approvedAmountCents"));assertEquals("200000",result.get("executedAmountCents"));assertEquals("50000",result.get("remainingAmountCents"));assertEquals("PARTIALLY_EXECUTED",result.get("executionState"));
  FeeExecutionProjectionController.Peer altered=(edge,path,body,r)->{var response=new LinkedHashMap<String,Object>(exact.call(edge,path,body,r));response.put("authorityDigest","0".repeat(64));return response;};assertEquals(503,assertThrows(com.ias.trust.Problem.class,()->new FeeExecutionProjectionController(source,access,altered).projection(group.toString(),completion.toString(),request)).status);
 }
}
